// Local contract subset observed in publisher/collect.go and publisher/search.go.
// Fixtures are generated by TestCollectorAgainstPostmanSimulation. The test PKCS7
// payload is deliberately synthetic: these fixtures never leave the test runner.
const http = require("node:http");
const fixtureNames = ["root", "dep", "extra"].flatMap(name => [name + ".vsix", name + ".sigzip"]);
let fixtures = new Map();
let mode = "normal";
const send = (res, code, value) => { res.writeHead(code, {"Content-Type":"application/json"}); res.end(JSON.stringify(value)); };
http.createServer(async (req, res) => {
  const route = new URL(req.url, "http://localhost").pathname;
  let body = req.body;
  if (body === undefined && req.method === "POST") { let raw = ""; for await (const chunk of req) raw += chunk; body = raw ? JSON.parse(raw) : {}; }
  if (Buffer.isBuffer(body)) body = JSON.parse(body.toString());
  if (typeof body === "string") body = JSON.parse(body);
  if (route === "/control/fixtures" && req.method === "POST") {
    if (!body || fixtureNames.some(name => typeof body[name] !== "string" || !body[name] || body[name].length > (1 << 20))) {
      return send(res, 400, {error:"six bounded base64 fixtures required"});
    }
    fixtures = new Map(fixtureNames.map(name => [name, Buffer.from(body[name], "base64")]));
    return send(res, 200, {fixtures:fixtures.size});
  }
  if (route === "/control/mode" && req.method === "POST") { mode = body.mode; return send(res, 200, {mode}); }
  if (mode === "slow") await new Promise(resolve => setTimeout(resolve, 5000));
  if (mode === "unavailable") return send(res, 503, {error:"simulated upstream unavailable"});
  if (route === "/_apis/public/gallery/extensionquery" && req.method === "POST") {
    const filter = body.filters?.[0];
    if (!filter || !Array.isArray(filter.criteria)) return send(res, 400, {error:"query required"});
    const exact = filter.criteria.find(c => c.filterType === 7)?.value;
    const names = exact ? [exact.split(".")[1]] : ["root", "dep", "extra"];
    const extensions = names.filter(name => ["root", "dep", "extra"].includes(name)).map(name => ({
      extensionName:name, displayName:"Sample " + name, shortDescription:"Local simulation fixture",
      publisher:{publisherName:"sample",publisherId:"00000000-0000-0000-0000-000000000001",displayName:"Sample",domain:"https://example.com",isDomainVerified:true},
      versions:[{version:"1.0.0",properties:[],files:[
        {assetType:"Microsoft.VisualStudio.Services.VSIXPackage",source:"https://marketplace.visualstudio.com/assets/"+name+".vsix"},
        {assetType:"Microsoft.VisualStudio.Services.VsixSignature",source:"https://marketplace.visualstudio.com/assets/"+name+".sigzip"}
      ]}]
    }));
    return send(res, 200, {results:[{extensions}]});
  }
  const asset = /^\/assets\/(root|dep|extra)\.(vsix|sigzip)$/.exec(route);
  if (asset && req.method === "GET") {
    const name = mode === "bad-signature" && asset[2] === "sigzip" ? "extra" : asset[1];
    const bytes = fixtures.get(name + "." + asset[2]);
    if (!bytes) return send(res, 500, {error:"Run the Go simulation test to load fixtures"});
    res.writeHead(200, {"Content-Type":"application/octet-stream"});
    return res.end(bytes);
  }
  send(res, 501, {error:"Endpoint is outside this test contract"});
}).listen(process.env.PORT || 4500);
